#!/usr/bin/env node
import assert from "node:assert/strict";
import { copyFile, mkdir, readFile, readdir, writeFile } from "node:fs/promises";
import { createHash, createPublicKey, verify as verifySignature } from "node:crypto";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { acceptStagingOperationReceiptV1, createInitialStagingSupervisorStateV1, digest } from "./lib/morphogenesis-staging-supervisor.mjs";
import { awsKmsPublicKeyPemV1, createAwsJsonRunner, resolveAwsKmsEd25519V1, signAwsKmsEd25519V1 } from "./lib/aws-kms-ed25519.mjs";
const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), ".."); const options = parse(process.argv.slice(2)); const mode = options.mode ?? "contract-smoke";
if (mode === "contract-smoke") console.log(JSON.stringify({ status: "passed", completedSupervisorRequired: true, receiptReplayRequired: true, kmsAttestationRequired: true, executionPermitted: false, stagingQualification: "not-established", productionClaimPermitted: false }, null, 2));
else if (mode === "assemble-sign") {
  allowed(["aws-cli", "aws-profile", "aws-region", "confirm", "mode", "output-directory", "supervisor-directory"]); assert.equal(options.confirm, "ASSEMBLE_MORPHOGENESIS_DISTRIBUTED_STAGING_BUNDLE"); const supervisorDirectory = external(required("supervisor-directory")); const outputDirectory = external(required("output-directory")); const [config, state, authorization, publicKeyPem, eventText] = await Promise.all([json(path.join(supervisorDirectory, "supervisor-config.json")), json(path.join(supervisorDirectory, "supervisor-state.json")), json(path.join(supervisorDirectory, "authorization.json")), readFile(path.join(supervisorDirectory, "campaign-public-key.pem"), "utf8"), readFile(path.join(supervisorDirectory, "supervisor-events.jsonl"), "utf8")]); assert.equal(state.status, "completed"); assert.equal(state.stagingQualification, "beta1-distributed-staging-profile-established"); assert.equal(state.productionClaimPermitted, false); verifyAuthorization(config, authorization, publicKeyPem);
  const receiptDirectory = path.join(supervisorDirectory, "receipts"); const names = (await readdir(receiptDirectory)).sort(); assert.equal(names.length, state.acceptedReceiptDigests.length); let reconstructed = { ...createInitialStagingSupervisorStateV1(config), status: "authorized" }; const receiptManifest = [];
  for (const name of names) { assert.match(name, /^[0-9]{4}-[0-9a-f]{16}\.json$/u); const bytes = await readFile(path.join(receiptDirectory, name)); const signed = JSON.parse(bytes); const { receiptDigest, proof, ...body } = signed; assert.equal(receiptDigest, digest("agentplat-agent-morphogenesis-beta1-staging-operation-receipt-v1", body)); verifyProof(config, proof, publicKeyPem, operationSigningBytes(body)); reconstructed = acceptStagingOperationReceiptV1(config, reconstructed, body); receiptManifest.push({ name, bytes: bytes.byteLength, sha256: createHash("sha256").update(bytes).digest("hex"), receiptDigest, operationId: body.operationId, operationType: body.operationType, sequence: body.sequence }); }
  assert.equal(reconstructed.status, "completed"); for (const key of ["baselineScenarioIds", "postUpgradeScenarioIds", "partitionAuthorityScenarioIds", "faultCycles", "rollingDeploymentCycles", "schemaUpgradeCycles", "backupRestoreCycles", "keyRotationCycles", "isolationPassed", "alertDeliveryPassed", "soak", "duplicateMaterialEffects", "unauthorizedActivations", "lostCommittedReceipts", "morphologyHeadForks", "crossTenantEffects", "crossMissionEffects", "missionContinuityRatio", "stagingQualification", "productionReadiness", "productionClaimPermitted"]) assert.deepEqual(reconstructed[key], state[key]); assert.deepEqual(receiptManifest.map(({ receiptDigest }) => receiptDigest), state.acceptedReceiptDigests);
  const events = eventText.split("\n").filter(Boolean).map(JSON.parse); let previous = null; for (const [index, event] of events.entries()) { const { eventDigest, ...body } = event; assert.equal(event.sequence, index + 1); assert.equal(event.previousEventDigest, previous); assert.equal(eventDigest, digest("staging-supervisor-event-v1", body)); previous = eventDigest; } assert.equal(previous, state.lastEventDigest); assert.equal(events.length, names.length + 2);
  const receiptRoot = digest("staging-operation-receipt-manifest-v1", receiptManifest); const eventRoot = digest("staging-supervisor-event-journal-v1", events); const body = { schemaVersion: 1, kind: "agentplat-agent-morphogenesis-beta1-staging-evidence-bundle-v1", sourceCommit: config.sourceCommit, profileId: config.profileId, profileDigest: config.profileDigest, configDigest: config.configDigest, inventoryDigest: config.inventoryDigest, deploymentReceiptDigest: config.deploymentReceiptDigest, authorizationDigest: authorization.authorizationDigest, campaignKeyId: config.campaignKeyId, receiptManifest, receiptRoot, eventCount: events.length, eventRoot, supervisorRevision: state.revision, completedOperationCount: names.length, baselineScenarioCount: state.baselineScenarioIds.length, postUpgradeScenarioCount: state.postUpgradeScenarioIds.length, partitionAuthorityScenarioCount: state.partitionAuthorityScenarioIds.length, soak: state.soak, stagingQualification: "beta1-distributed-staging-profile-established", operationalReadiness: "staging-profile-established", experimentalEvidence: "not-collected", productionReadiness: "not-established", productionClaimPermitted: false, securityCertificationClaimPermitted: false };
  const bundle = { ...body, bundleDigest: digest("staging-evidence-bundle-v1", body) }; const runAws = createAwsJsonRunner({ executable: options["aws-cli"], profile: options["aws-profile"], region: options["aws-region"] }); const material = await resolveAwsKmsEd25519V1({ keyId: config.campaignKeyId, runAws }); assert.equal(material.publicKeyFingerprint, config.campaignPublicKeyFingerprint); const attestationBody = { schemaVersion: 1, kind: "agentplat-agent-morphogenesis-beta1-staging-attestation-v1", bundleDigest: bundle.bundleDigest, sourceCommit: config.sourceCommit, receiptRoot, eventRoot, stagingQualification: bundle.stagingQualification, operationalReadiness: bundle.operationalReadiness, productionReadiness: "not-established", productionClaimPermitted: false, signedAt: new Date().toISOString() }; const signature = await signAwsKmsEd25519V1({ material, message: attestationSigningBytes(attestationBody), runAws }); const attestation = { ...attestationBody, attestationDigest: digest("staging-attestation-v1", attestationBody), proof: { algorithm: "Ed25519", keyId: material.keyId, signature } };
  await mkdir(outputDirectory, { recursive: false }); await mkdir(path.join(outputDirectory, "operation-receipts")); await Promise.all([writeJson(outputDirectory, "staging-bundle.json", bundle), writeJson(outputDirectory, "staging-attestation.json", attestation), writeFile(path.join(outputDirectory, "staging-public-key.pem"), awsKmsPublicKeyPemV1(material), { encoding: "utf8", flag: "wx" }), writeFile(path.join(outputDirectory, "staging-qualification-report.md"), report(bundle), { encoding: "utf8", flag: "wx" }), ...names.map((name) => copyFile(path.join(receiptDirectory, name), path.join(outputDirectory, "operation-receipts", name)))]);
  console.log(JSON.stringify({ status: "assembled-and-signed", bundleDigest: bundle.bundleDigest, attestationDigest: attestation.attestationDigest, receiptRoot, eventRoot, stagingQualification: bundle.stagingQualification, operationalReadiness: bundle.operationalReadiness, productionReadiness: "not-established", productionClaimPermitted: false, outputDirectory }, null, 2));
} else if (mode === "verify") {
  allowed(["bundle-directory", "mode"]); const directory = external(required("bundle-directory")); const [bundle, attestation, publicKeyPem] = await Promise.all([json(path.join(directory, "staging-bundle.json")), json(path.join(directory, "staging-attestation.json")), readFile(path.join(directory, "staging-public-key.pem"), "utf8")]); const { bundleDigest, ...bundleBody } = bundle; assert.equal(bundleDigest, digest("staging-evidence-bundle-v1", bundleBody)); const { attestationDigest, proof, ...attestationBody } = attestation; assert.equal(attestationDigest, digest("staging-attestation-v1", attestationBody)); assert.equal(attestation.bundleDigest, bundleDigest); verifyProof({ campaignKeyId: proof.keyId }, proof, publicKeyPem, attestationSigningBytes(attestationBody)); const receiptDirectory = path.join(directory, "operation-receipts"); const names = (await readdir(receiptDirectory)).sort(); assert.equal(names.length, bundle.receiptManifest.length); for (const [index, entry] of bundle.receiptManifest.entries()) { assert.equal(names[index], entry.name); const bytes = await readFile(path.join(receiptDirectory, entry.name)); assert.equal(bytes.byteLength, entry.bytes); assert.equal(createHash("sha256").update(bytes).digest("hex"), entry.sha256); const signed = JSON.parse(bytes); const { receiptDigest, proof: receiptProof, ...body } = signed; assert.equal(receiptDigest, entry.receiptDigest); verifyProof({ campaignKeyId: proof.keyId }, receiptProof, publicKeyPem, operationSigningBytes(body)); } assert.equal(digest("staging-operation-receipt-manifest-v1", bundle.receiptManifest), bundle.receiptRoot); assert.equal(bundle.productionReadiness, "not-established"); assert.equal(bundle.productionClaimPermitted, false); console.log(JSON.stringify({ status: "verified", bundleDigest, attestationDigest, operationReceipts: names.length, stagingQualification: bundle.stagingQualification, productionClaimPermitted: false }, null, 2));
} else throw new TypeError("staging_bundle_mode_invalid");
function verifyAuthorization(config, authorization, publicKeyPem) { const { authorizationDigest, proof, ...body } = authorization; assert.equal(authorizationDigest, digest("staging-authorization-v1", body)); assert.equal(body.configDigest, config.configDigest); assert.equal(body.deploymentReceiptDigest, config.deploymentReceiptDigest); assert.ok(Date.parse(body.expiresAt) > Date.parse(body.issuedAt)); verifyProof(config, proof, publicKeyPem, Buffer.from(`agentplat-agent-morphogenesis-beta1-staging-authorization-v1\n${JSON.stringify(body)}`)); }
function verifyProof(config, proof, publicKeyPem, bytes) { assert.equal(proof.algorithm, "Ed25519"); assert.equal(proof.keyId, config.campaignKeyId); assert.equal(verifySignature(null, bytes, createPublicKey(publicKeyPem), Buffer.from(proof.signature, "base64url")), true); }
function operationSigningBytes(body) { return Buffer.from(`agentplat-agent-morphogenesis-beta1-staging-operation-receipt-v1\n${JSON.stringify(body)}`); } function attestationSigningBytes(body) { return Buffer.from(`agentplat-agent-morphogenesis-beta1-staging-attestation-v1\n${JSON.stringify(body)}`); }
function report(bundle) { return `# Agent Morphogenesis Beta 1 distributed staging qualification\n\nSource commit: \`${bundle.sourceCommit}\`\n\nBundle digest: \`${bundle.bundleDigest}\`\n\nStaging qualification: **${bundle.stagingQualification}**\n\nOperational readiness: **${bundle.operationalReadiness}**\n\nThe bundle contains ${bundle.completedOperationCount} KMS-signed operation receipts, ${bundle.baselineScenarioCount} baseline scenarios, ${bundle.postUpgradeScenarioCount} post-upgrade scenarios and ${bundle.partitionAuthorityScenarioCount} partition authority scenarios.\n\nProduction readiness remains **not-established** and production claims remain prohibited.\n`; }
function required(name) { const value = options[name]; if (!value) throw new TypeError(`${name} is required`); return value; } function external(value) { const resolved = path.resolve(value); const relative = path.relative(root, resolved); if (relative === "" || (!relative.startsWith("..") && !path.isAbsolute(relative))) throw new TypeError("staging bundle paths must be external"); return resolved; } function allowed(names) { for (const name of Object.keys(options)) if (!names.includes(name)) throw new TypeError(`unsupported option: ${name}`); } function parse(args) { const result = {}; for (let index = 0; index < args.length; index += 1) { if (args[index] === "--") continue; if (!args[index].startsWith("--")) throw new TypeError("invalid option"); const value = args[index + 1]; if (!value || value.startsWith("--")) throw new TypeError(`missing value for ${args[index]}`); result[args[index].slice(2)] = value; index += 1; } return result; } async function json(file) { return JSON.parse(await readFile(file, "utf8")); } async function writeJson(directory, name, value) { await writeFile(path.join(directory, name), `${JSON.stringify(value, null, 2)}\n`, { encoding: "utf8", flag: "wx" }); }
